from PIL import Image, ImageDraw, ImageFont
def font(s):
    for f in ('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',):
        try: return ImageFont.truetype(f,s)
        except: pass
    return ImageFont.load_default()
def sheet(items,out,cols=None,pad=24,bg=(243,245,248)):
    ims=[(t,Image.open(p)) for t,p in items]; cols=cols or len(ims); rows=[ims[i:i+cols] for i in range(0,len(ims),cols)]
    W=max(sum(i.width for _,i in r)+pad*(len(r)+1) for r in rows); H=sum(max(i.height for _,i in r)+pad+34 for r in rows)+pad
    S=Image.new('RGB',(W,H),bg); d=ImageDraw.Draw(S); y=pad
    for r in rows:
        x=pad
        for t,i in r: d.text((x,y),t,fill=(20,33,49),font=font(17)); S.paste(i,(x,y+30)); x+=i.width+pad
        y+=max(i.height for _,i in r)+pad+34
    S.save(out)
